import React, { useEffect } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';

const Workbooks = () => {
  useEffect(() => {
    document.title = 'Workbooks | Pearlson Languages';
  }, []);

  return (
    <div className="relative min-h-screen w-full flex items-center justify-center overflow-hidden bg-cream">
      {/* Subtle flag accents */}
      <div className="pointer-events-none absolute inset-0 opacity-10">
        <div className="absolute -top-24 -left-24 w-80 h-80 rounded-full" style={{ background: 'linear-gradient(135deg, #0055A4 0%, #FFFFFF 50%, #EF4135 100%)', filter: 'blur(30px)' }} />
        <div className="absolute -bottom-24 -right-24 w-96 h-96 rounded-full" style={{ background: 'linear-gradient(135deg, #000000 0%, #DD0000 50%, #FFCC00 100%)', filter: 'blur(30px)' }} />
      </div>

      <div className="container-custom py-24 text-center relative z-10">
        <motion.h1
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6 }}
          className="text-4xl md:text-5xl font-bold text-black mb-6"
        >
          Interactive Workbooks
        </motion.h1>
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.2, duration: 0.6 }}
          className="text-gray-700 max-w-2xl mx-auto mb-10"
        >
          We are crafting engaging, curriculum-aligned French and German workbooks with games, audio, and interactive practice.
        </motion.p>

        {/* Coming soon animation */}
        <motion.div
          initial={{ scale: 0.9, opacity: 0 }}
          animate={{ scale: [0.95, 1.05, 1], opacity: 1 }}
          transition={{ duration: 1.2, ease: 'easeOut' }}
          className="mx-auto w-64 h-64 md:w-80 md:h-80 rounded-2xl shadow-xl bg-white flex items-center justify-center relative overflow-hidden"
        >
          <div className="absolute inset-0 animate-pulse" style={{ background: 'repeating-linear-gradient(45deg, rgba(255,69,0,0.05) 0, rgba(255,69,0,0.05) 10px, rgba(0,0,0,0.03) 10px, rgba(0,0,0,0.03) 20px)' }} />
          <motion.div
            initial={{ y: 20, opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ delay: 0.3 }}
            className="text-center"
          >
            <div className="text-6xl">📘</div>
            <div className="text-2xl font-bold text-[#FF4500] mt-2">Coming Soon</div>
            <div className="text-gray-600 mt-1">French & German interactive practice</div>
          </motion.div>
        </motion.div>

        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ delay: 0.6 }}
          className="mt-10 flex items-center justify-center gap-4"
        >
          <Link to="/courses" className="bg-[#FF4500] hover:bg-[#cc3700] text-white font-semibold px-6 py-2 rounded shadow focus:outline-none focus:ring-2 focus:ring-[#FF4500] focus:ring-offset-2">
            Explore Courses
          </Link>
          <Link to="/contact" className="bg-white hover:bg-gray-50 text-gray-800 border border-gray-200 font-semibold px-6 py-2 rounded shadow focus:outline-none focus:ring-2 focus:ring-gray-300 focus:ring-offset-2">
            Contact Us
          </Link>
        </motion.div>
      </div>
    </div>
  );
};

export default Workbooks;
